static void send_capabilities(int fd_out, struct packet_reader *reader)
{
	const char *hash_name;
	const char *promisor_remote_info;

	if (server_supports_v2("agent"))
		packet_write_fmt(fd_out, "agent=%s", git_user_agent_sanitized());

	if (server_feature_v2("object-format", &hash_name)) {
		int hash_algo = hash_algo_by_name(hash_name);
		if (hash_algo == GIT_HASH_UNKNOWN)
			die(_("unknown object format '%s' specified by server"), hash_name);
		reader->hash_algo = &hash_algos[hash_algo];
		packet_write_fmt(fd_out, "object-format=%s", reader->hash_algo->name);
	} else {
		reader->hash_algo = &hash_algos[GIT_HASH_SHA1_LEGACY];
	}
	}

	if (!(flags & TRANSPORT_RECURSE_SUBMODULES_ONLY)) {
		trace2_region_enter("transport_push", "push_refs", r);
		push_ret = transport->vtable->push_refs(transport, remote_refs, flags);
		trace2_region_leave("transport_push", "push_refs", r);
	} else
		push_options_supported = 1;

	if (!server_supports_hash(r->hash_algo->name, &object_format_supported))
		die(_("the receiving end does not support this repository's hash algorithm"));

// advertised object-format (fetch-pack.c). This keeps the client a conformant
// peer that never sends a capability the server did not offer.
func ClientCapabilities(server capability.List) capability.List {
	var caps capability.List
	if agent := server.Get(capability.Agent); len(agent) > 0 {
		caps.Set(capability.Agent, capability.DefaultAgent())
	}
	// A format go-git does not know is not echoed. Fetch then refuses the
	// server in ReconcileObjectFormatV2, as git's send_capabilities does for
	// every command; ls-refs does not check, so listing such a server's refs
	// still works.
	if of := server.Get(capability.ObjectFormat); len(of) > 0 {
		switch f := config.ObjectFormat(of[0]); f {
		case config.SHA1, config.SHA256:
			caps.Set(capability.ObjectFormat, f.String())
		}
			return err
		}
	}

	if len(cmds) == 0 {
		return NoErrAlreadyUpToDate
	}

// escapeClientValue returns v with its control characters and invalid UTF-8
// replaced by '?', for echoing a client's value in an error. The vreportf
// behind git's die does the same for control characters other than tab and
// newline; those two are replaced here as well, so the value cannot add lines
// to the error.
func escapeClientValue(v string) string {
	return strings.Map(func(r rune) rune {
		if r == utf8.RuneError || unicode.IsControl(r) {
			return '?'
		}
		return r
	}, v)
}
	require.NoError(t, waitForPort(ctx, port))
}

// requireGitDaemon skips t unless git's exec path holds git-daemon.
func requireGitDaemon(t testing.TB) {
	t.Helper()
	out, err := gitenv.Command("git", "--exec-path").Output()
	if err != nil {
		t.Skipf("git daemon: cannot find git's exec path: %v", err)
	}
	name := "git-daemon"
	if runtime.GOOS == "windows" {
		name += ".exe"
	}
	if _, err := os.Stat(filepath.Join(strings.TrimSpace(string(out)), name)); err != nil {
		t.Skipf("git daemon is not installed: %v", err)
	}
}

